SELECT qb.id, qb.code, qb.qc_dept_id, qb.qc_dept_name, qb.qc_user_id, qb.qc_user_name, qb.purchase_order_id, qb.purchase_order_code,qb.qc_status, qb.qc_date,qb.supplier_id,qb.warehouse_id, qi.qc_type,qi.is_inside, qp.sku_id,qi.total_qty, qi.qc_qty,qi.qc_good_qty, qi.qc_bad_qty,qi.qc_result, qi.handle_mode_dict, qi.bad_description, qi.qc_good_rate,qi.qc_bad_rate FROM qc_bill qb LEFT JOIN qc_info qi ON qb.id=qi.main_id AND qi.is_deleted=FALSE LEFT JOIN qc_product qp ON qp.main_id=qi.main_id AND qb.is_deleted=FALSE WHERE qb.is_deleted=FALSE
AND qb.qc_status=#{params.searchType}
AND qb.purchase_order_code LIKE concat('%', #{params.purchaseOrderCode} ,'%')
AND qp.sku_no IN
#{skuNo}
AND qb.qc_status IN
#{qcStatus}
AND qi.qc_type =#{params.qcType}
AND qi.is_inside =#{params.isInside}
AND qb.supplier_id IN
#{supplierId}
AND qb.warehouse_id IN
#{warehouseId}
AND bd.result_dict IN
#{qcResult}
AND qi.handle_mode_dict IN
#{handleMode}
AND qb.create_user_id IN
#{createUserId}
AND qb.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > qb.create_time
